export interface RunFailedData {
  run: Run;
  error: ErrorInfo;
}
/**
 * A run stopped to wait on a person, for each interrupt it lists.
 */
export interface RunInterruptedData {
  run: Run;
  interrupts: Interrupt[];
}
/**
 * An interrupted run carried on.
 */
export interface RunResumedData {
  run: Run;
}
/**
 * A run began, answering the messages it lists. None for a run carried on after a lost node.
 */
export interface RunStartedData {
  run: Run;
}
/**
 * Someone took a secret out of the vault.
 */
export interface SecretRemovedData {
  secret: {
    name: string;
  };
  /**
   * The org, as acme/, or the user, as acme/@jon/, it is kept for; none where it is the whole deployment's.
   */
  owner?: string;
  actor?: Principal;
}
/**
 * Someone sealed a secret in the vault.
 */
export interface SecretStoredData {
  secret: {
    name: string;
  };
  /**
   * The org, as acme/, or the user, as acme/@jon/, it is kept for; none where it is the whole deployment's.
   */
  owner?: string;
  actor?: Principal;
}
/**
 * Someone added an MCP server for an owner's agents.
 */
export interface ServerAddedData {
  server: {
    name: string;
    url: string;
  };
  /**
   * The org, as acme/, or the user, as acme/@jon/, whose agents it serves.
   */
  owner: string;
  actor?: Principal;
}
/**
 * Someone removed an MCP server an owner had added.
 */
export interface ServerRemovedData {
  server: {
    name: string;
  };
  /**
   * The org, as acme/, or the user, as acme/@jon/, whose agents it serves.
   */
  owner: string;
  actor?: Principal;
}
/**
 * A named step ended.
 */
export interface StepCompletedData {
  /**
   * How the step ended: cancelled where a stopped turn cut it short.
   */
  status: "ok" | "error" | "cancelled";
  duration_ms: DurationMs;
  error?: ErrorInfo;
}
/**
 * A named step began.
 */
export interface StepStartedData {
  step: {
    name: string;
  };
}
/**
 * A subagent answered.
 */
export interface SubagentCompletedData {
  agent?: {
    id?: string;
    name?: string;
  };
  message: Message;
  duration_ms: DurationMs;
}
/**
 * A subagent failed.
 */
export interface SubagentFailedData {
  agent?: {
    id?: string;
    name?: string;
  };
  error: ErrorInfo;
  duration_ms: DurationMs;
}
/**
 * A subagent was handed a task.
 */
export interface SubagentStartedData {
  agent?: {
    id?: string;
    name?: string;
  };
  prompt: string;
}
/**
 * Someone made an API token.
 */
export interface TokenCreatedData {
  token: {
    id: string;
    name: string;
  };
  /**
   * The prefix of the agents it reaches: acme/ for an org's own, acme/@jon/ for a user's, acme/* for the org and every one of its users', or empty for every agent.
   */
  scope: string;
  /**
   * What it may do to them.
   */
  can: string[];
  for?: Principal;
  actor?: Principal;
}
/**
 * Someone revoked an API token.
 */
export interface TokenRevokedData {
  token: {
    id: string;
  };
  actor?: Principal;
}
/**
 * A tool call answered, or was answered from the ledger when replayed.
 */
export interface ToolCallCompletedData {
  tool: Tool;
  status: "ok" | "error";
  error?: ErrorInfo;
  replayed: boolean;
  served_by?: ServedBy;
  cost?: Cost;
}
/**
 * A tool call was refused without running.
 */
export interface ToolCallDeniedData {
  tool: Tool;
  reason: string;
  decided: Decided;
}
/**
 * A tool call reported progress. Live: never stored.
 */
export interface ToolCallProgressData {
  tool: Tool;
  progress: number;
  total?: number;
}
/**
 * A tool call began.
 */
export interface ToolCallStartedData {
  tool: Tool;
  decided: Decided;
}
/**
 * A trigger came due.
 */
export interface TriggerFiredData {
  trigger: {
    name: string;
  };
  status: "asked" | "nothing_new" | "busy" | "no_agent" | "missed" | "failed";
}
/**
 * Someone removed one of an agent's triggers.
 */
export interface TriggerRemovedData {
  agent: {
    /**
     * The agent's ID.
     */
    id: string;
  };
  trigger: {
    name: string;
  };
  actor?: Principal;
}
/**
 * Someone set one of an agent's triggers.
 */
export interface TriggerSetData {
  agent: {
    /**
     * The agent's ID.
     */
    id: string;
  };
  trigger: {
    name: string;
  };
  actor?: Principal;
}

/** Each event type, and the data its events carry. */
export interface EventData {
  "wardrik.agent.cancelled": AgentCancelledData;
  "wardrik.agent.cleared": AgentClearedData;
  "wardrik.agent.defined": AgentDefinedData;
  "wardrik.agent.forgotten": AgentForgottenData;
  "wardrik.agent.moved": AgentMovedData;
  "wardrik.agent.spawned": AgentSpawnedData;
  "wardrik.agent.started": AgentStartedData;
  "wardrik.agent.stopped": AgentStoppedData;
  "wardrik.agents.reloaded": AgentsReloadedData;
  "wardrik.conversation.cleared": ConversationClearedData;
  "wardrik.conversation.compacted": ConversationCompactedData;
  "wardrik.interrupt.resolved": InterruptResolvedData;
  "wardrik.message.completed": MessageCompletedData;
  "wardrik.message.created": MessageCreatedData;
  "wardrik.message.delta": MessageDeltaData;
  "wardrik.message.started": MessageStartedData;
  "wardrik.reasoning.delta": ReasoningDeltaData;
  "wardrik.room.bound": RoomBoundData;
  "wardrik.room.unbound": RoomUnboundData;
  "wardrik.run.cancelled": RunCancelledData;
  "wardrik.run.completed": RunCompletedData;
  "wardrik.run.deadline_exceeded": RunDeadlineExceededData;
  "wardrik.run.failed": RunFailedData;
  "wardrik.run.interrupted": RunInterruptedData;
  "wardrik.run.resumed": RunResumedData;
  "wardrik.run.started": RunStartedData;
  "wardrik.secret.removed": SecretRemovedData;
  "wardrik.secret.stored": SecretStoredData;
  "wardrik.server.added": ServerAddedData;
  "wardrik.server.removed": ServerRemovedData;
  "wardrik.step.completed": StepCompletedData;
  "wardrik.step.started": StepStartedData;
  "wardrik.subagent.completed": SubagentCompletedData;
  "wardrik.subagent.failed": SubagentFailedData;
  "wardrik.subagent.started": SubagentStartedData;
  "wardrik.token.created": TokenCreatedData;
  "wardrik.token.revoked": TokenRevokedData;
  "wardrik.tool_call.completed": ToolCallCompletedData;
  "wardrik.tool_call.denied": ToolCallDeniedData;
  "wardrik.tool_call.progress": ToolCallProgressData;
  "wardrik.tool_call.started": ToolCallStartedData;
  "wardrik.trigger.fired": TriggerFiredData;
  "wardrik.trigger.removed": TriggerRemovedData;
  "wardrik.trigger.set": TriggerSetData;
}

/** An event's type, as its CloudEvent names it. */
export type EventType = keyof EventData;

/** A Wardrik event: a CloudEvent whose data is its type's. */
export type WardrikEvent = {
  [T in EventType]: Omit<Envelope, "type" | "data"> & { type: T; data: EventData[T] };
}[EventType];

/** The event of one type. */
export type EventOf<T extends EventType> = Extract<WardrikEvent, { type: T }>;
